class InvalidPoint(Exception):
    pass


class Point:
    __slots__ = ("x", "y")

    def __init__(self, x=None, y=None):
        self.x = x
        self.y = y

    def is_infinity(self):
        return self.x is None and self.y is None

    def __eq__(self, other):
        return isinstance(other, Point) and self.x == other.x and self.y == other.y

    def __repr__(self):
        if self.is_infinity():
            return "Point(infinity)"
        return f"Point({self.x}, {self.y})"


O = Point()


class Curve:
    def __init__(self, p, a, b):
        self.p = p
        self.a = a % p
        self.b = b % p

    def is_on_curve(self, P):
        if P.is_infinity():
            return True
        if not (0 <= P.x < self.p and 0 <= P.y < self.p):
            return False
        left = (P.y * P.y) % self.p
        right = (pow(P.x, 3, self.p) + self.a * P.x + self.b) % self.p
        return left == right

    def add(self, P, Q):
        if P.is_infinity():
            return Q
        if Q.is_infinity():
            return P

        p = self.p
        x1, y1 = P.x % p, P.y % p
        x2, y2 = Q.x % p, Q.y % p

        if x1 == x2 and (y1 + y2) % p == 0:
            return O

        try:
            if x1 == x2 and y1 == y2:
                den = (2 * y1) % p
                if den == 0:
                    return O
                lam = ((3 * x1 * x1 + self.a) * pow(den, -1, p)) % p
            else:
                den = (x2 - x1) % p
                lam = ((y2 - y1) * pow(den, -1, p)) % p
        except ValueError as exc:
            raise InvalidPoint("non-invertible denominator") from exc

        x3 = (lam * lam - x1 - x2) % p
        y3 = (lam * (x1 - x3) - y1) % p
        return Point(x3, y3)

    def neg(self, P):
        if P.is_infinity():
            return P
        return Point(P.x, (-P.y) % self.p)

    def mul(self, k, P):
        if k < 0:
            return self.mul(-k, self.neg(P))
        result = O
        addend = P
        while k:
            if k & 1:
                result = self.add(result, addend)
            addend = self.add(addend, addend)
            k >>= 1
        return result


