import os
import sys
from dataclasses import dataclass
from hashlib import sha256

from Crypto.Cipher import AES
from Crypto.Random import get_random_bytes
from Crypto.Util.Padding import pad

from ecc import Curve, Point, InvalidPoint, int_to_bytes
import params


@dataclass
class OracleResponse:
    iv: bytes
    ct: bytes


def load_secret():
    value = os.environ.get("SERVER_D")
    if value:
        return int(value, 0)
    for path in ("server_secret.txt", "/app/server_secret.txt", "/flag_server_secret.txt"):
        if os.path.exists(path):
            with open(path, "r", encoding="utf-8") as f:
                return int(f.read().strip(), 0)
    raise RuntimeError("server secret is not configured")


def load_flag():
    value = os.environ.get("FLAG")
    if value:
        return value.encode()
    for path in ("/flag", "/app/flag"):
        if os.path.exists(path):
            with open(path, "rb") as f:
                return f.read().strip()
    return b"local dynamic flag placeholder"


def derive_key(P):
    if P.is_infinity():
        raise InvalidPoint("infinity shared secret")
    return sha256(int_to_bytes(P.x) + int_to_bytes(P.y)).digest()


def encrypt_flag(secret_d, flag):
    curve = Curve(params.P, params.A, params.B)
    peer = Point(params.PEER_X, params.PEER_Y)
    shared = curve.mul(secret_d, peer)
    key = derive_key(shared)
    iv = get_random_bytes(16)
    ct = AES.new(key, AES.MODE_CBC, iv).encrypt(pad(flag, 16))
    return iv, ct


def render_public_output(flag_iv=None, flag_ct=None):
    if flag_iv is None:
        flag_iv_text = "provided_by_server"
    else:
        flag_iv_text = flag_iv.hex()
    if flag_ct is None:
        flag_ct_text = "provided_by_server"
    else:
        flag_ct_text = flag_ct.hex()

    lines = [
        "Broken ECDH public output",
        f"p = {params.P}",
        f"a = {params.A}",
        f"b = {params.B}",
        f"order = {params.ORDER}",
        f"q = {params.Q}",
        f"cofactor = {params.COFACTOR}",
        f"G = ({params.GX}, {params.GY})",
        f"Q = ({params.QX}, {params.QY})",
        f"B_pub = ({params.PEER_X}, {params.PEER_Y})",
        f"max_queries = {params.MAX_QUERIES}",
        f"known_plaintext = {params.KNOWN_PLAINTEXT.hex()}",
        f"flag_iv = {flag_iv_text}",
        f"flag_ct = {flag_ct_text}",
    ]
    return "\n".join(lines)


class Oracle:
    def __init__(self, secret_d=None, flag=None, max_queries=params.MAX_QUERIES):
        self.secret_d = load_secret() if secret_d is None else secret_d
        self.flag = load_flag() if flag is None else flag
        self.flag_iv, self.flag_ct = encrypt_flag(self.secret_d, self.flag)
        self.max_queries = max_queries
        self.used = 0
        self.curve = Curve(params.P, params.A, params.B)

    def query(self, x, y):
        if self.used >= self.max_queries:
            raise InvalidPoint("query limit exceeded")
        if not (0 <= x < params.P and 0 <= y < params.P):
            raise InvalidPoint("coordinate out of range")

        self.used += 1
        peer = Point(x, y)

        # Vulnerability: the implementation never calls self.curve.is_on_curve(peer).
        shared = self.curve.mul(self.secret_d, peer)
        key = derive_key(shared)
        iv = get_random_bytes(16)
        ct = AES.new(key, AES.MODE_CBC, iv).encrypt(pad(params.KNOWN_PLAINTEXT, 16))
        return OracleResponse(iv, ct)


def main():
    oracle = Oracle()
    print("Welcome to Broken ECDH.")
    print(render_public_output(oracle.flag_iv, oracle.flag_ct))
    print(f"You have {params.MAX_QUERIES} oracle queries.")
    print("Send your peer public key as: x y")
    sys.stdout.flush()

    for _ in range(params.MAX_QUERIES):
        line = sys.stdin.readline()
        if not line:
            break
        try:
            xs, ys = line.strip().split()
            response = oracle.query(int(xs, 0), int(ys, 0))
            print(f"iv = {response.iv.hex()}")
            print(f"ct = {response.ct.hex()}")
        except Exception:
            print("invalid")
        sys.stdout.flush()


if __name__ == "__main__":
    main()
